namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public string ImageUrl { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int RecipeCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;
    // In-memory ratings: recipeId -> list of ratings
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day right with hearty morning meals", RecipeCount = 2 },
            new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals that keep you going", RecipeCount = 2 },
            new() { Name = "Dinner", Icon = "🍝", Description = "Satisfying evening dishes for the whole family", RecipeCount = 2 },
            new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats to end any meal", RecipeCount = 2 },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy buttermilk pancakes perfect for a weekend brunch.",
                Ingredients = ["2 cups flour", "2 tbsp sugar", "2 tsp baking powder", "1 tsp salt", "2 eggs", "1¾ cups milk", "¼ cup melted butter"],
                Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Cook on a greased griddle over medium heat until bubbles form, then flip."],
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple, healthy, and endlessly customizable.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "Salt and pepper", "Red pepper flakes", "1 tbsp lemon juice"],
                Steps = ["Toast the bread until golden.", "Mash avocado with lemon juice, salt, and pepper.", "Spread onto toast and top with red pepper flakes."],
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch",
                Description = "A crisp, garlicky classic with homemade dressing.",
                Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan", "2 tbsp Caesar dressing", "1 clove garlic"],
                Steps = ["Wash and chop the romaine lettuce.", "Toss with Caesar dressing and minced garlic.", "Top with croutons and shaved parmesan."],
                AverageRating = 4.0, RatingCount = 6
            },
            new()
            {
                Id = 4, Title = "Grilled Chicken Wrap", Category = "Lunch",
                Description = "A protein-packed wrap that's great on the go.",
                Ingredients = ["1 grilled chicken breast", "1 large tortilla", "Lettuce, tomato, onion", "2 tbsp ranch dressing"],
                Steps = ["Slice the grilled chicken.", "Layer chicken and vegetables on the tortilla.", "Drizzle with ranch and wrap tightly."],
                AverageRating = 4.3, RatingCount = 10
            },
            new()
            {
                Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich, slow-simmered meat sauce over al dente pasta.",
                Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp oregano"],
                Steps = ["Cook spaghetti according to package directions.", "Brown ground beef with onion and garlic.", "Add tomatoes, tomato paste, and oregano; simmer 20 minutes.", "Serve sauce over pasta."],
                AverageRating = 4.7, RatingCount = 20
            },
            new()
            {
                Id = 6, Title = "Teriyaki Salmon", Category = "Dinner",
                Description = "Glazed salmon fillets with a sweet and savory finish.",
                Ingredients = ["2 salmon fillets", "3 tbsp soy sauce", "2 tbsp mirin", "1 tbsp honey", "1 tsp ginger, grated"],
                Steps = ["Mix soy sauce, mirin, honey, and ginger for the glaze.", "Marinate salmon for 15 minutes.", "Bake at 400°F (200°C) for 12–15 minutes, basting with glaze."],
                AverageRating = 4.6, RatingCount = 14
            },
            new()
            {
                Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Warm, gooey chocolate cake with a molten center.",
                Ingredients = ["200g dark chocolate", "100g butter", "2 eggs", "2 egg yolks", "¼ cup sugar", "2 tbsp flour"],
                Steps = ["Melt chocolate and butter together.", "Whisk eggs, yolks, and sugar until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Bake in greased ramekins at 425°F (220°C) for 12 minutes."],
                AverageRating = 4.9, RatingCount = 25
            },
            new()
            {
                Id = 8, Title = "Strawberry Shortcake", Category = "Desserts",
                Description = "Light, fluffy biscuits layered with berries and cream.",
                Ingredients = ["2 cups flour", "¼ cup sugar", "1 tbsp baking powder", "½ cup cold butter", "¾ cup milk", "2 cups strawberries", "1 cup whipped cream"],
                Steps = ["Mix flour, sugar, and baking powder; cut in butter.", "Stir in milk until dough forms; bake biscuits at 425°F for 12 minutes.", "Slice strawberries and toss with a little sugar.", "Split biscuits, layer with berries and whipped cream."],
                AverageRating = 4.4, RatingCount = 11
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAllRecipes() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);

        var category = _categories.FirstOrDefault(c =>
            c.Name.Equals(recipe.Category, StringComparison.OrdinalIgnoreCase));
        if (category != null)
            category.RecipeCount++;
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);

        var recipe = GetRecipeById(recipeId);
        if (recipe is null) return;

        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = Math.Round(_ratings[recipeId].Average(), 1);
    }

    public List<string> GetCategoryNames() => _categories.Select(c => c.Name).ToList();
}

