@page "/recipes/{CategoryName}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="mb-2">
                            <span class="text-warning">@GetStarDisplay(recipe.AverageRating)</span>
                            <small class="text-muted">(@recipe.RatingCount ratings)</small>
                        </div>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private List<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }

    private static string GetStarDisplay(double rating)
    {
        int fullStars = (int)rating;
        bool halfStar = rating - fullStars >= 0.5;
        int emptyStars = 5 - fullStars - (halfStar ? 1 : 0);
        return new string('★', fullStars) + (halfStar ? "½" : "") + new string('☆', emptyStars);
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-link">← Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h3>Steps</h3>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h4>Rate this Recipe</h4>
            <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
        </div>
    </div>

    <a href="recipes/@recipe.Category.ToLower()" class="btn btn-link">← Back to @recipe.Category</a>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@using RecipeShare.Services
@inject RecipeService RecipeService

<div>
    <div style="font-size: 2rem; cursor: pointer; user-select: none;">
        @for (int i = 1; i <= 5; i++)
        {
            int star = i;
            <span @onclick="() => SubmitRating(star)"
                  @onmouseover="() => hoverStar = star"
                  @onmouseout="() => hoverStar = 0"
                  style="color: @(star <= (hoverStar > 0 ? hoverStar : selectedStar) ? "#ffc107" : "#dee2e6"); transition: color 0.15s;">
                ★
            </span>
        }
    </div>

    @if (submitted)
    {
        <div class="alert alert-success mt-2 py-1 px-2 d-inline-block">
            Thanks! You rated this @selectedStar out of 5 stars.
        </div>
    }
    else
    {
        <small class="text-muted">Click a star to rate</small>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selectedStar;
    private int hoverStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

@page "/submit"
@using RecipeShare.Services
@using RecipeShare.Models
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (isSubmitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added. <a href="recipe/@submittedId">View it here</a>.</p>
    </div>
    <button class="btn btn-primary" @onclick="ResetForm">Submit Another</button>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label">Recipe Title</label>
            <InputText @bind-Value="title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => title" />
        </div>

        <div class="mb-3">
            <label class="form-label">Category</label>
            <InputSelect @bind-Value="category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategoryNames())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label">Description</label>
            <InputTextArea @bind-Value="description" class="form-control" rows="2"
                           placeholder="A brief description of your dish" />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients</label>
            <p class="text-muted small">One ingredient per line</p>
            <InputTextArea @bind-Value="ingredientsText" class="form-control" rows="5"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        </div>

        <div class="mb-3">
            <label class="form-label">Steps</label>
            <p class="text-muted small">One step per line</p>
            <InputTextArea @bind-Value="stepsText" class="form-control" rows="5"
                           placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        </div>

        <button type="submit" class="btn btn-success"
                disabled="@(string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category))">
            Submit Recipe
        </button>
    </EditForm>
}

<div class="mt-3">
    <a href="/" class="btn btn-link">← Back to Home</a>
</div>

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string description = string.Empty;
    private string ingredientsText = string.Empty;
    private string stepsText = string.Empty;
    private bool isSubmitted;
    private int submittedId;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category))
            return;

        var recipe = new Recipe
        {
            Title = title.Trim(),
            Category = category,
            Description = description.Trim(),
            Ingredients = ingredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = stepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };

        RecipeService.AddRecipe(recipe);
        submittedId = recipe.Id;
        isSubmitted = true;
    }

    private void ResetForm()
    {
        title = string.Empty;
        category = string.Empty;
        description = string.Empty;
        ingredientsText = string.Empty;
        stepsText = string.Empty;
        isSubmitted = false;
    }
}

